"""SCOREBOARD.md, rendered from results/scoreboard.json and never typed by hand.

``craton check`` re-renders the board and fails if the Markdown differs from the JSON, so a
number can only reach the scoreboard through a benchmark run and the ratchet.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from craton.bench.catalog import BY_ID, CATALOG
from craton.bench.results import Scoreboard, ScoreEntry
from craton.paths import data_health_json, scoreboard_json, scoreboard_md

HEADER = (
    "<!-- Generated by `craton scoreboard` from results/scoreboard.json and\n"
    "     results/data_health.json. Do not edit by hand: `craton check` fails if this file\n"
    "     and the JSON disagree. -->\n"
)

ARROW = {"lower": "↓", "higher": "↑"}


def _fmt(entry: ScoreEntry) -> str:
    return f"{entry.mean:.4g} ± {entry.std:.2g} {ARROW[entry.direction]}"


def _n(x: int) -> str:
    return f"{x:,}"


def _rejected(rejects: dict[str, int]) -> str:
    total = sum(rejects.values())
    if not total:
        return "0"
    top = sorted(rejects.items(), key=lambda kv: (-kv[1], kv[0]))[:2]
    return f"{_n(total)} ({', '.join(f'{k} {_n(v)}' for k, v in top)})"


def _says(name: str, health: dict[str, Any]) -> str:
    """One line on what an adapter's data holds, from its health entry."""
    if "seismic_catalog" in health:
        h = health["seismic_catalog"]
        big = h["largest"]
        types = ", ".join(f"{k} {_n(v)}" for k, v in h["magnitude_types"].items())
        mc = h["mc_ml_per_year"]
        years = sorted(mc)
        picks = [y for y in years if int(y) % 10 == 5] or years[:: max(1, len(years) // 4)]
        mc_text = " · ".join(f"{y} {mc[y]:.1f}" for y in picks)
        parts = [f"largest {big['type']} {big['magnitude']:g} on {big['day']}", types]
        if mc_text:
            parts.append(f"completeness Mc(ML) {mc_text}")
        if h["longest_gap_days"] is not None:
            parts.append(f"longest quiet spell {h['longest_gap_days']:g} days")
        return "; ".join(parts)
    if "gnss_daily" in health:
        h = health["gnss_daily"]
        return (
            f"{h['stations']} stations, median {_n(h['median_days_per_station'])} days each, "
            f"median coverage {h['median_coverage']:.0%}, {_n(h['gaps_over_30_days'])} gaps "
            "over 30 days"
        )
    if "solid_earth_tide" in health:
        h = health["solid_earth_tide"]
        pk = h["peak_m"]
        return (
            f"{_n(h['at_events'])} at earthquakes + {_n(h['hourly'])} hourly; peak "
            f"{pk['u']:.3f} m up, {pk['n']:.3f} m north, {pk['e']:.3f} m east"
        )
    return "·"


def _span(health: dict[str, Any]) -> str:
    h = next(iter(health.values()), None)
    if not h or h["first"] is None:
        return "·"
    return f"{h['first']} → {h['last']}"


def render_data(report: dict[str, Any] | None) -> list[str]:
    lines = ["", "## Data", ""]
    regions = (report or {}).get("regions", {})
    if not regions:
        lines.append("No data built yet. `craton data fetch` then `craton data build`.")
        return lines
    lines.append(
        "Measured on the latest build of each region by `craton data build`. The snapshot id is "
        "the hash of every token file, so it only changes if a byte of the data does."
    )
    for name in sorted(regions):
        r = regions[name]
        lines += [
            "",
            f"### {name} · snapshot `{r['snapshot']}` · {r['window'][0][:10]} → "
            f"{r['window'][1][:10]}",
            "",
            "| Source | Tokens | Span | Rejected | What it holds |",
            "|---|---|---|---|---|",
        ]
        for aname in sorted(r["adapters"]):
            a = r["adapters"][aname]
            lines.append(
                f"| `{aname}` | {_n(a['tokens'])} | {_span(a['health'])} | "
                f"{_rejected(a['rejects'])} | {_says(aname, a['health'])} |"
            )
    return lines


def render(board: Scoreboard, data: dict[str, Any] | None = None) -> str:
    lines: list[str] = [HEADER, "# Scoreboard", ""]
    lines += [
        "Every number here comes from a script and is a mean ± std over 3 seeds. "
        "The ratchet only lets a number in if no other task gets worse beyond noise, "
        "so this table can only improve.",
        "",
        "## Headline",
        "",
        "| | Task | Now | Arrives |",
        "|---|---|---|---|",
    ]
    for task in (t for t in CATALOG if t.headline):
        entry = board.entries.get(task.task_id)
        now = _fmt(entry) if entry else "not measured yet"
        lines.append(
            f"| **{task.name}** | {task.task_id} · {task.measures} | {now} | {task.phase} |"
        )

    lines += [
        "",
        "## Every task",
        "",
        "| ID | Task | Score | Model | Run | Phase |",
        "|---|---|---|---|---|---|",
    ]
    known = {t.task_id for t in CATALOG}
    for task_id in sorted(known | set(board.entries)):
        planned = BY_ID.get(task_id)
        entry = board.entries.get(task_id)
        name = planned.name if planned else task_id
        phase = planned.phase if planned else "—"
        if entry:
            score, run = _fmt(entry), f"`{entry.run_id}`"
            lines.append(f"| {task_id} | {name} | {score} | {entry.model} | {run} | {phase} |")
        else:
            lines.append(f"| {task_id} | {name} | · | · | · | {phase} |")

    lines += ["", "## History", ""]
    if board.history:
        lines += ["| Accepted (UTC) | Run | Model | Ratchet |", "|---|---|---|---|"]
        for h in reversed(board.history):
            when = h.accepted.strftime("%Y-%m-%d %H:%M")
            lines.append(f"| {when} | `{h.run_id}` | {h.model} | {h.summary} |")
    else:
        lines.append(
            "No runs yet. The first real numbers are the simple baselines in P3, scored before "
            "any model exists, so the first model has something honest to beat."
        )
    lines += render_data(data)
    lines.append("")
    return "\n".join(lines)


def _load_data(root: Path) -> dict[str, Any] | None:
    path = data_health_json(root)
    if not path.is_file():
        return None
    out: dict[str, Any] = json.loads(path.read_text(encoding="utf-8"))
    return out


def write(root: Path) -> Path:
    board = Scoreboard.load(scoreboard_json(root))
    out = scoreboard_md(root)
    out.write_text(render(board, _load_data(root)), encoding="utf-8", newline="\n")
    return out


def integrity_problem(root: Path) -> str | None:
    """None if SCOREBOARD.md is exactly what the JSON renders to."""
    md = scoreboard_md(root)
    if not md.exists():
        return "SCOREBOARD.md is missing. Run `craton scoreboard`."
    expected = render(Scoreboard.load(scoreboard_json(root)), _load_data(root))
    actual = md.read_text(encoding="utf-8").replace("\r\n", "\n")
    if actual != expected:
        return (
            "SCOREBOARD.md doesn't match results/scoreboard.json (edited by hand?). "
            "Run `craton scoreboard` to regenerate it."
        )
    return None
